#!/usr/bin/env python3
"""Derives internal/theme/expected_test.go mechanically from src/theme.rs.

Run from anywhere:  python3 internal/theme/testdata/gen_expected.py
The Go implementation in theme.go is typed by hand; this script is the second,
independent transcription that the tests compare it with (the table uses plain
Color literals, not the helpers of theme.go).  The mapping of
crossterm's named colours to 256-colour palette indices is read from the
crossterm source that Cargo.lock pins (style/types/colored.rs), not typed here.
"""
import glob
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
RS = open(os.path.join(ROOT, "src", "theme.rs")).read()

lock = open(os.path.join(ROOT, "Cargo.lock")).read()
version = re.search(r'name = "crossterm"\nversion = "([^"]+)"', lock).group(1)
colored = glob.glob(os.path.expanduser(f"~/.cargo/registry/src/*/crossterm-{version}/src/style/types/colored.rs"))[0]
ANSI = {}
for name, index in re.findall(r'Color::(\w+) => f\.write_str\("5;(\d+)"\)', open(colored).read()):
    ANSI[name] = int(index)


def go_color(value):
    value = value.strip().rstrip(",")
    m = re.fullmatch(r"rgb\(0x([0-9a-f]{6})\)", value)
    if m:
        h = m.group(1)
        return f"Color{{Kind: ColorRGB, R: 0x{h[0:2]}, G: 0x{h[2:4]}, B: 0x{h[4:6]}}}"
    m = re.fullmatch(r"Color::(\w+)", value)
    if m:
        if m.group(1) == "Reset":
            return "Color{Kind: ColorReset}"
        return f"Color{{Kind: ColorAnsi, Index: {ANSI[m.group(1)]}}}"
    sys.exit(f"unrecognised colour {value!r}")


FIELD = {"bold_keywords": "boldKeywords", "background": "Background", "foreground": "Foreground", "muted": "Muted",
         "surface": "Surface", "macro_color": "macroColor", "type_color": "typeColor"}


def go_field(name):
    return FIELD.get(name, name)


variants = re.search(r"pub enum Theme \{(.*?)\n\}", RS, re.S).group(1)
variants = re.findall(r"^\s+(\w+),", variants.replace("#[default]", ""), re.M)

out = ["// Code generated by testdata/gen_expected.py from src/theme.rs; DO NOT EDIT.", "",
       "package theme", "", 'import "github.com/fclaude/coigue/internal/syntax"', ""]

out.append("// expectedThemes lists the variants in the order of the Rust enum.")
out.append("var expectedThemes = []Theme{" + ", ".join(variants) + "}")
out.append("")

palette_src = re.search(r"pub fn palette\(self\) -> Palette \{(.*?)\n    \}\n\}", RS, re.S).group(1)
out.append("var expectedPalettes = map[Theme]Palette{")
for variant, body in re.findall(r"Self::(\w+) => Palette \{(.*?)\n            \},", palette_src, re.S):
    out.append(f"\t{variant}: {{")
    for field, value in re.findall(r"^\s+(\w+): (.*),$", body, re.M):
        v = value if field == "bold_keywords" else go_color(value)
        out.append(f"\t\t{go_field(field)}: {v},")
    out.append("\t},")
out.append("}")
out.append("")

name_src = re.search(r"pub fn name\(self\).*?\{(.*?)\n    \}", RS, re.S).group(1)
out.append("var expectedNames = map[Theme]string{")
for variant, name in re.findall(r'Self::(\w+) => "([^"]+)"', name_src):
    out.append(f'\t{variant}: "{name}",')
out.append("}")
out.append("")

parse_src = re.search(r"pub fn parse\(name: &str\).*?\{(.*?)\n    \}", RS, re.S).group(1)
out.append("var expectedParse = map[string]Theme{")
for arm, variant in re.findall(r"^\s+((?:\"[^\"]+\"(?: \| )?)+) => Some\(Self::(\w+)\)", parse_src, re.M):
    for name in re.findall(r'"([^"]+)"', arm):
        out.append(f'\t"{name}": {variant},')
out.append("}")
out.append("")

choices = re.search(r'pub const CHOICES: &str = "([^"]+)";', RS).group(1)
out.append(f'const expectedChoices = "{choices}"')
out.append("")
completions = re.search(r"COMPLETIONS: &\[&str\] = &\[(.*?)\];", RS, re.S).group(1)
out.append("var expectedCompletions = []string{" + ", ".join(re.findall(r'"[^"]+"', completions)) + "}")
out.append("")

syntax_src = re.search(r"pub fn syntax\(self, style: Style\) -> Color \{(.*?)\n    \}", RS, re.S).group(1)
out.append("// expectedSyntax is every arm of Palette::syntax, one row per style.")
out.append("var expectedSyntax = []struct {")
out.append("\tstyle syntax.Style")
out.append("\tcolor func(Palette) Color")
out.append("}{")
for styles, field in re.findall(r"^\s+((?:Style::\w+(?: \| )?)+) => self\.(\w+),", syntax_src, re.M):
    for style in re.findall(r"Style::(\w+)", styles):
        out.append(f"\t{{syntax.{style}, func(p Palette) Color {{ return p.{go_field(field)} }}}},")
out.append("}")
out.append("")

diag_src = re.search(r"pub fn diagnostic\(self, severity: u8\) -> Color \{(.*?)\n    \}", RS, re.S).group(1)
out.append("var expectedDiagnostic = []struct {")
out.append("\tseverity uint8")
out.append("\tcolor    func(Palette) Color")
out.append("}{")
for sev, field in re.findall(r"^\s+(\d+) => self\.(\w+),", diag_src, re.M):
    out.append(f"\t{{{sev}, func(p Palette) Color {{ return p.{go_field(field)} }}}},")
field = re.search(r"^\s+_ => self\.(\w+),", diag_src, re.M).group(1)
out.append(f"\t{{0, func(p Palette) Color {{ return p.{go_field(field)} }}}}, // the `_` arm")
out.append(f"\t{{4, func(p Palette) Color {{ return p.{go_field(field)} }}}},")
out.append(f"\t{{255, func(p Palette) Color {{ return p.{go_field(field)} }}}},")
out.append("}")
out.append("")

open(os.path.join(HERE, "..", "expected_test.go"), "w").write("\n".join(out))
